input.command:
test -f /synthesis/output/environment/Dockerfile \
  && test -f /synthesis/output/environment/setup.sh \
  && test -f /synthesis/output/environment/setup-overlay.sh \
  && test -f /synthesis/output/environment/smoke_test.sh \
  && test -d /synthesis/output/environment/assets \
  || { echo "REFUSING_BUILD_MISSING_ENV_TREE"; exit 1; }
docker info >/dev/null 2>&1 || { echo "DOCKER_INFO_FAIL"; exit 1; }
echo BUILD_START=$(date -u +%Y-%m-%dT%H:%M:%SZ)
START=$(date +%s)
docker build -t synth-env:03 /synthesis/output/environment 2>&1 | tee /synthesis/logs/build.log
EC=${PIPESTATUS[0]}
END=$(date +%s)
echo BUILD_EXIT=$EC BUILD_SECONDS=$((END-START))
tail -40 /synthesis/logs/build.log

START=$(date +%s)
docker build -t synth-env:03 /synthesis/output/environment 2>&1 | tee /synthesis/logs/build.log
EC=${PIPESTATUS[0]}
END=$(date +%s)
echo BUILD_EXIT=$EC BUILD_SECONDS=$((END-START))
tail -30 /synthesis/logs/build.log

START=$(date +%s)
docker run --rm synth-env:03 bash /opt/env/smoke_test.sh 2>&1 | tee /synthesis/logs/smoke.log
EC=${PIPESTATUS[0]}
END=$(date +%s)
echo SMOKE_EXIT=$EC SMOKE_SECONDS=$((END-START))
cat /synthesis/logs/smoke.log

START=$(date +%s)
docker build -t synth-env:03 /synthesis/output/environment 2>&1 | tee /synthesis/logs/build.log | tail -20
EC=${PIPESTATUS[0]}
END=$(date +%s)
echo BUILD_EXIT=$EC BUILD_SECONDS=$((END-START))
if [ "$EC" -eq 0 ]; then
  docker run --rm synth-env:03 bash /opt/env/smoke_test.sh 2>&1 | tee /synthesis/logs/smoke.log
  echo SMOKE_EXIT=${PIPESTATUS[0]}
fi
